"""Compile the bilingual detector catalog so mod resource namespace order cannot hide it."""
from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
lines = ["package local.pixelmon.backport.client;", "import java.util.Map;",
         "/** Generated by tools/build_detector_config_catalog.py. */",
         "public final class DetectorConfigCatalog {", "    private DetectorConfigCatalog(){}"]
for locale, name in [("zh_cn", "ZH"), ("en_us", "EN")]:
    data = json.loads((root / "resources/assets/pixelmondetector/lang" / (locale + ".json")).read_text(encoding="utf-8"))
    lines.append("    private static final Map<String,String> " + name + "=Map.ofEntries(")
    lines.append(",\n".join("        Map.entry(" + json.dumps(key, ensure_ascii=False) + "," + json.dumps(value, ensure_ascii=False) + ")" for key, value in data.items()))
    lines.append("    );")
lines += ['    public static String get(String key,String locale){return ("zh_cn".equals(locale)?ZH:"en_us".equals(locale)?EN:Map.<String,String>of()).get(key);}', "}"]
(root / "src/local/pixelmon/backport/client/DetectorConfigCatalog.java").write_text("\n".join(lines) + "\n", encoding="utf-8")
